INSERT INTO journal_settings (journal_id,name,value) VALUES (1,'description','<p>The <em>Journal of Intelligent Decision Making and Information Science</em> is an interdisciplinary, peer-reviewed journal that publishes cutting-edge research on data-driven decision-making, artificial intelligence, and information management. The journal provides a platform for innovative approaches that enhance decision processes and optimize information systems, serving researchers, industry professionals, and decision-makers across diverse fields such as healthcare, finance, environmental science, and technology.</p>');
