INSERT INTO journal_settings (journal_id,name,value) VALUES (1,'readerInfo','<p>We encourage readers to sign up for the publishing notification service for this journal. Use the <a href="__JURL__/user/register">Register</a> link at the top of the home page for the journal. This registration will result in the reader receiving the Table of Contents by email for each new issue of the journal. This list also allows the journal to claim a certain level of support or readership. See the journal''s <a href="__JURL__/about/submissions#privacyStatement">Privacy Statement</a>, which assures readers that their name and email address will not be used for other purposes.</p>');
INSERT INTO journal_settings (journal_id,name,value) VALUES (1,'authorInfo','<p>Interested in submitting to this journal? We recommend that you review the <a href="__JURL__/about">About the Journal</a> page for the journal''s section policies, as well as the <a href="__JURL__/about/submissions#authorGuidelines">Author Guidelines</a>. Authors need to <a href="__JURL__/user/register">register</a> with the journal prior to submitting or, if already registered, can simply <a href="https://jidmis.org/index.php/index/login">log in</a> and begin the five-step process.</p>');
INSERT INTO journal_settings (journal_id,name,value) VALUES (1,'librarianInfo','We encourage research librarians to list this journal among their library''s electronic journal holdings. As well, it may be worth noting that this journal''s open source publishing system is suitable for libraries to host for their faculty members to use with journals they are involved in editing (see <a href="http://pkp.sfu.ca/ojs">Open Journal Systems</a>).');
